class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];

        int L = firstLen, M = secondLen;

        // sum of length len starting at i: pref[i+len] - pref[i]
        int[] sumL = new int[n - L + 1];
        for (int i = 0; i <= n - L; ++i) sumL[i] = pref[i + L] - pref[i];
        int[] sumM = new int[n - M + 1];
        for (int i = 0; i <= n - M; ++i) sumM[i] = pref[i + M] - pref[i];

        int ans = 0;

        // Case 1: L before M
        int maxLeft = 0;
        // j is start of M, must satisfy j >= L and j <= n-M
        for (int j = L; j <= n - M; ++j) {
            // include sumL[j-L] into maxLeft (covers starts up to j-L)
            maxLeft = Math.max(maxLeft, sumL[j - L]);
            ans = Math.max(ans, maxLeft + sumM[j]);
        }

        // Case 2: M before L
        maxLeft = 0;
        for (int j = M; j <= n - L; ++j) {
            maxLeft = Math.max(maxLeft, sumM[j - M]);
            ans = Math.max(ans, maxLeft + sumL[j]);
        }

        return ans;
    }
}

